INSERT INTO TB_CATECHISM_UNIT (UNIT_ID, CATECHISM_ID, PARENT_UNIT_ID, UNIT_TYPE_CD, UNIT_NO, TITLE, SORT_ORDER, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (3, 1, NULL, 'PART', 3, '감사에 관하여', 3, 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_UNIT (UNIT_ID, CATECHISM_ID, PARENT_UNIT_ID, UNIT_TYPE_CD, UNIT_NO, TITLE, SORT_ORDER, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (4, 1, 3, 'LORDS_DAY', 45, '우리의 구속에 관하여', 45, 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_QA (QA_ID, CATECHISM_ID, UNIT_ID, QUESTION_NO, QUESTION, SORT_ORDER, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (1, 1, 4, 116, '왜 그리스도인들은 기도해야 합니까?', 1, 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_ANSWER (ANSWER_ID, QA_ID, SORT_ORDER, CONTENT, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (1, 1, 1, '기도가 하나님께서 요구하시는 감사의 삶 중에서 가장 중요한 부분이기 때문입니다. 그리고 하나님께서는 그의 은혜와 성령을 주시기를, 그러한 은사를 위해서 지속적으로 기도하고 마음으로 아파하는 이들에게, 그리고 그것에 감사하는 이들에게만 주시기 때문입니다.', 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_QA (QA_ID, CATECHISM_ID, UNIT_ID, QUESTION_NO, QUESTION, SORT_ORDER, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (2, 1, 4, 117, '어떠한 기도가 하나님을 기쁘시게 하며, 어떠한 기도에 하나님께서 응답하십니까?', 2, 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_ANSWER (ANSWER_ID, QA_ID, SORT_ORDER, CONTENT, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (2, 2, 1, '첫째, 말씀을 통해서 우리에게 계시되신 오직 유일하신 참된 하나님께 우리의 마음으로부터 우리에게 기도하도록 가르치신 모든 것을 위해서 기도해야 합니다.', 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_ANSWER (ANSWER_ID, QA_ID, SORT_ORDER, CONTENT, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (3, 2, 2, '둘째, 거룩하신 하나님 앞에 우리가 엎드리기 위해서 우리의 필요와 비참함을 철저하게 인식해야 합니다.', 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_ANSWER (ANSWER_ID, QA_ID, SORT_ORDER, CONTENT, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (4, 2, 3, '셋째, 우리는 다음과 같이 변치 않는 기초 위에 서야 합니다: 우리가 비록 받을 자격이 없으나 우리 구주 그리스도로 말미암아 하나님께서는 우리의 기도를 분명히 들으십니다. 하나님께서 그의 말씀에 그렇게 우리에게 약속하셨습니다.', 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_QA (QA_ID, CATECHISM_ID, UNIT_ID, QUESTION_NO, QUESTION, SORT_ORDER, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (3, 1, 4, 118, '하나님께서 무엇을 위해서 기도하라고 가르치셨습니까?', 3, 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_ANSWER (ANSWER_ID, QA_ID, SORT_ORDER, CONTENT, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (5, 3, 1, '우리 주 그리스도께서 우리에게 가르쳐 주신 기도에 포함되어 있는 것처럼 우리의 영육간에 필요한 모든 것들을 위해서 기도하라고 하셨습니다.', 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_QA (QA_ID, CATECHISM_ID, UNIT_ID, QUESTION_NO, QUESTION, SORT_ORDER, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (4, 1, 4, 119, '주님께서 가르쳐 주신 기도는 무엇입니까?', 4, 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
INSERT INTO TB_CATECHISM_ANSWER (ANSWER_ID, QA_ID, SORT_ORDER, CONTENT, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT) VALUES (6, 4, 1, '하늘에 계신 우리 아버지여, 이름이 거룩히 여김을 받으시오며, 나라가 임하옵시며, 뜻이 하늘에서 이룬 것 같이 땅에서도 이루어지이다. 오늘날 우리에게 일용할 양식을 주옵시고, 우리가 우리에게 죄지은 자를 사하여 준 것 같이 우리 죄를 사하여 주옵시고 우리를 시험에 들게 하지 마옵시고, 다만 악에서 구하옵소서. 대개 나라와 권세와 영광이 아버지께 영원히 있사옵나이다. 아멘.', 'system', SYSTIMESTAMP, 'system', SYSTIMESTAMP);
